# Parse the yield table from June 1970 bulletin

with open('/app/resources/treasury_bulletin_1970_06.txt', 'r') as f:
    content = f.read()

lines = content.split('\n')

# Find the line with table header
in_table = False
data_rows = []
for i, line in enumerate(lines):
    if '| Period | Treasury bonds' in line and 'Aa new corporate bonds' in line:
        in_table = True
        continue
    if in_table:
        if line.startswith('|') and 'Monthly series' not in line and 'Weekly series' not in line:
            if 'nan' in line or 'Period' in line:
                continue
            data_rows.append(line)
        elif 'Weekly series' in line:
            break

# Parse each row - only first 12 months (one year)
count = 0
for row in data_rows:
    parts = [p.strip() for p in row.split('|')[1:-1]]
    if len(parts) >= 3 and parts[0]:
        month = parts[0]
        treasury = parts[1].replace(' 4/', '').replace(' 5/', '').replace(' 3/', '')
        aa_corp = parts[2]
        if month in ['Jan.', 'Feb.', 'Mar.', 'Apr.', 'May', 'June', 'July', 'Aug.', 'Sept.', 'Oct.', 'Nov.', 'Dec.']:
            try:
                t = float(treasury)
                a = float(aa_corp)
                spread = a - t
                print(f"{month}: Treasury={t}, Aa corp={a}, Spread={spread:.2f}")
                count += 1
                if count >= 12:
                    break
            except:
                pass
EOF
